<script setup lang="ts">
import { Head, useForm } from '@inertiajs/vue3'; import { Button } from '@/components/ui/button'; import { Input } from '@/components/ui/input'; import { Label } from '@/components/ui/label';
type Package = { id: string; name: string; sku: string; physical_quantity: string; components: { name: string; quantity: string; physical_quantity: string }[] }; type Conversion = { id: string; document_number: string; type: string; package: string; quantity: string; total_cost: number; creator: string; created_at: string };
const props = defineProps<{ packages: Package[]; conversions: Conversion[] }>(); const now = new Date(); const localNow = new Date(now.getTime() - now.getTimezoneOffset() * 60000).toISOString().slice(0, 16); const form = useForm({ package_presentation_id: props.packages[0]?.id ?? '', conversion_type: 'assembly', quantity: '1', effective_at: localNow }); const submit = () => form.post('/inventory/packages', { preserveScroll: true }); const money = new Intl.NumberFormat('es-CO', { style: 'currency', currency: 'COP', maximumFractionDigits: 0 });
</script>
<template><Head title="Conversiones de paquetes" /><main class="flex flex-1 flex-col gap-6 p-4 md:p-6"><header><h1 class="text-2xl font-semibold">Armar y desarmar paquetes</h1><p class="text-sm text-muted-foreground">Convierte presentaciones del mismo producto conservando el costo total.</p></header><section class="max-w-2xl rounded-xl border bg-card p-5"><form class="grid gap-4 md:grid-cols-2" @submit.prevent="submit"><div class="grid gap-2 md:col-span-2"><Label>Paquete</Label><select v-model="form.package_presentation_id" required class="h-9 rounded-md border bg-transparent px-3 text-sm"><option v-for="pack in packages" :key="pack.id" :value="pack.id">{{ pack.name }} (existencia {{ pack.physical_quantity }})</option></select></div><div class="grid gap-2"><Label>Operación</Label><select v-model="form.conversion_type" class="h-9 rounded-md border bg-transparent px-3 text-sm"><option value="assembly">Armar</option><option value="disassembly">Desarmar</option></select></div><div class="grid gap-2"><Label>Cantidad de paquetes</Label><Input v-model="form.quantity" type="number" min="0.000001" step="any" required /></div><div class="grid gap-2"><Label>Fecha efectiva</Label><Input v-model="form.effective_at" type="datetime-local" required /></div><div class="flex items-end"><Button type="submit" :disabled="form.processing || packages.length === 0">Confirmar conversión</Button></div></form></section><section><h2 class="mb-3 font-semibold">Composición y disponibilidad</h2><div class="grid gap-3 md:grid-cols-2"><article v-for="pack in packages" :key="pack.id" class="rounded-xl border bg-card p-4"><h3 class="font-medium">{{ pack.name }}</h3><p class="text-xs text-muted-foreground">{{ pack.sku }} · {{ pack.physical_quantity }} paquetes</p><ul class="mt-3 space-y-1 text-sm"><li v-for="component in pack.components" :key="component.name">{{ component.quantity }} × {{ component.name }} <span class="text-muted-foreground">(disponible {{ component.physical_quantity }})</span></li></ul></article></div></section><section class="overflow-x-auto rounded-xl border bg-card"><table class="w-full text-sm"><thead class="border-b bg-muted/40 text-left"><tr><th class="px-4 py-3">Documento</th><th class="px-4 py-3">Operación</th><th class="px-4 py-3">Paquete</th><th class="px-4 py-3 text-right">Cantidad</th><th class="px-4 py-3 text-right">Costo</th><th class="px-4 py-3">Fecha</th></tr></thead><tbody class="divide-y"><tr v-for="conversion in conversions" :key="conversion.id"><td class="px-4 py-3 font-medium">{{ conversion.document_number }}</td><td class="px-4 py-3">{{ conversion.type }}</td><td class="px-4 py-3">{{ conversion.package }}</td><td class="px-4 py-3 text-right">{{ conversion.quantity }}</td><td class="px-4 py-3 text-right">{{ money.format(conversion.total_cost) }}</td><td class="px-4 py-3">{{ conversion.created_at }}</td></tr></tbody></table></section></main></template>
